"""
    Orders column list to include primary keys first and then non primary
    key columns
    :param pks: primary key list
    :param columns: columns
    :return: primary key columns + non primary key columns ordered
    """
def order_columns(pks: Any, columns: Any) -> object {
    pk_list = [];
    non_pk_list = [];
    for c in columns {
        for pk in pks {
            if (c.get("name") == pk) {
                pk_list.append(c);
                break;
            } elif (pks[-1] == pk) {
                non_pk_list.append(c);
            }
        }
    }
    return (pk_list + non_pk_list);
}

"""Strips the suffix from a string if present.

    https://stackoverflow.com/a/1038999

    Arguments:
        text {str} -- String to check for suffix
        suffix {str} -- Suffix to look for.

    Keyword Arguments:
        case_insensitive {bool} -- Do a case insensitive match. (default: {False})

    Returns:
        str -- Suffix to look for.
    """
def strip_end(text: str, suffix: str, case_insensitive: bool = False) -> str {
    if case_insensitive {
        if not text.lower().endswith(suffix.lower()) {
            return text;
        }
    } elif not text.endswith(suffix) {
        return text;
    }
    return text[:(len(text) - len(suffix))];
}

"""
    Since I3 map names cannot start with a number, add a letter 'a' to any names starting with a
        number

    Args:
        name: The name to check for a beginning number

    Returns: The new name (unchanged if the name properly started with a letter)

    """
def check_and_fix_names_starting_with_numbers(name: Any) -> object {
    result = name;
    if name[0].isdigit() {
        result = "a" + name;
    }
    return result;
}

"""This function adds leading zeros to the input string. The output string will have length == out_len
    Args:
        input_string (str): the input string
        out_len (int): length of output string with leading zeros
    Returns:
        out_string (str): the initial string but wiht leading zeros up to out_len characters
    """
def add_leading_zeros(input_string: str, out_len: int) -> str {
    out_string = input_string.zfill(out_len);
    return out_string;
}

"""Compares two ages, returns 0 if they match, returns penalty of -1 otherwise.

    Conservative assumptions:
        1) If age cannot be cleanly cast to int, consider comparators to be a match
        2) If ages are within 2 years, consider comparators to be a match

    """
def age_similarity_scorer(age_1: Any, age_2: Any) -> object {
    try {
        age_1 = int(age_1);
    } except Exception as e {
        return 0;
    }
    try {
        age_2 = int(age_2);
    } except Exception as e {
        return 0;
    }
    if (abs((age_1 - age_2)) <= 2) {
        return 0;
    } else {
        return -1;
    }
}

